### B1-001: Required behavior

Keep the existing help command and its exact text unchanged. Add validate <file>, emitting a JSON array of {id, amount} records after validating the complete UTF-8 input.

### B1-002: Required behavior

Input is zero or more LF-separated rows id,amount, optionally ending with one LF. Each id matches [A-Za-z0-9_-]+ and is unique within the input. Each amount is ASCII decimal digits representing a nonnegative safe integer. Malformed, duplicate or invalid records make either data command exit 2 with empty stdout and INVALID_INPUT on stderr; never emit a partial result.

### B1-003: Required behavior

Add summarize <file>, emitting JSON {count,total} using the same row validation contract as validate. Empty input produces [] for validate and {count:0,total:0} for summarize.

### B1-004: Required behavior

Use dependency-free Node.js. Delivery has two packets: shared validation and validate first, then summarize consuming that same validation contract. Preserve unrelated fixture content and existing compatibility. No commit, installation or external action is authorized.
#!/usr/bin/env node
import { readFileSync } from 'node:fs';
import { parseRecords } from './records.mjs';

const [command, file] = process.argv.slice(2);
if (command === 'help') process.stdout.write('record-report: validate <file> | summarize <file>\n');
else if (command === 'validate') {
  try {
    const text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(readFileSync(file));
    const records = parseRecords(text);
    process.stdout.write(JSON.stringify(records) + '\n');
  } catch {
    process.stderr.write('INVALID_INPUT\n');
    process.exitCode = 2;
  }
} else { process.stderr.write('UNKNOWN_COMMAND\n'); process.exitCode = 2; }
export function parseRecords(text) {
  const records = [];
  const ids = new Set();
  if (text === '') return records;
  const rows = text.split('\n');
  if (rows.at(-1) === '') rows.pop();
  for (const row of rows) {
    const match = /^([A-Za-z0-9_-]+),([0-9]+)$/.exec(row);
    if (!match || match[0] !== row) throw new Error('Invalid record');
    const [, id, digits] = match;
    const amount = Number(digits);
    if (!Number.isSafeInteger(amount) || amount < 0 || ids.has(id)) {
      throw new Error('Invalid record');
    }
    ids.add(id);
    records.push({ id, amount });
  }
  return records;
}
import test from 'node:test';
import assert from 'node:assert/strict';
import { runCli } from './test-process.mjs';
test('existing help remains stable', () => { const r=runCli(['help']); assert.equal(r.status,0); assert.equal(r.signal,null); assert.equal(r.stderr,''); assert.equal(r.stdout,'record-report: validate <file> | summarize <file>\n'); });

import { mkdirSync, mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { join } from 'node:path';

function validateInput(input) {
  mkdirSync('.tmp', { recursive: true });
  const folder = mkdtempSync('.tmp/P1-');
  const file = join(folder, 'input records.txt');
  try {
    writeFileSync(file, input);
    return runCli(['validate', file], { env: {} });
  } finally {
    rmSync(folder, { recursive: true, force: true });
  }
}
function success(input, stdout) {
  assert.deepEqual(validateInput(input), { status: 0, signal: null, stdout, stderr: '' });
}
function invalid(input) {
  const r = validateInput(input);
  assert.equal(r.stdout, '');
  assert.equal(r.stderr, 'INVALID_INPUT\n');
  assert.equal(r.status, 2);
  assert.equal(r.signal, null);
}

test('P1 unknown command remains stable', () => {
  assert.deepEqual(runCli(['unknown'], { env: {} }), {
    status: 2, signal: null, stdout: '', stderr: 'UNKNOWN_COMMAND\n',
  });
});
test('P1 valid records with optional terminal LF', () => {
  for (const ending of ['', '\n']) {
    success('a,1\nB_-2,002' + ending, '[{"id":"a","amount":1},{"id":"B_-2","amount":2}]\n');
  }
});
test('P1 numeric boundaries', () => {
  success('a,0\nb,9007199254740991', '[{"id":"a","amount":0},{"id":"b","amount":9007199254740991}]\n');
  invalid('a,9007199254740992');
});
test('P1 empty input', () => success('', '[]\n'));
const invalidRows = [
  ['missing comma', 'a1'], ['extra comma', 'a,1,2'],
  ['empty id', ',1'], ['empty amount', 'a,'],
  ['space in id', 'a b,1'], ['dot in id', 'a.b,1'], ['non-ASCII id', 'é,1'],
  ['leading amount space', 'a, 1'], ['trailing amount space', 'a,1 '],
  ['plus sign', 'a,+1'], ['minus sign', 'a,-1'], ['decimal', 'a,1.0'],
  ['exponent', 'a,1e2'], ['non-ASCII digit', 'a,١'],
  ['only LF', '\n'], ['leading blank', '\na,1'],
  ['interior blank', 'a,1\n\nb,2'], ['two terminal LFs', 'a,1\n\n'],
  ['CRLF', 'a,1\r\n'], ['terminal CR', 'a,1\r'],
];
for (const [label, input] of invalidRows) {
  test('P1 invalid grammar: ' + label, () => invalid(input));
}
test('P1 duplicate IDs are case sensitive', () => {
  invalid('a,1\na,2');
  success('a,1\nA,2', '[{"id":"a","amount":1},{"id":"A","amount":2}]\n');
});
test('P1 malformed UTF-8', () => invalid(Buffer.from([0x61, 0x2c, 0xc3, 0x28])));
test('P1 BOM rejected', () => invalid('\uFEFFa,1'));
test('P1 late duplicate has no partial output', () => invalid('a,1\nb,2\na,3'));
test('P1 late malformed row has no partial output', () => invalid('a,1\nb,2\nbad'));
test('P1 parser owns independent arrays', async () => {
  const { parseRecords } = await import('./records.mjs');
  const first = parseRecords('a,1');
  const second = parseRecords('a,1');
  assert.notStrictEqual(first, second);
  first[0].amount = 99;
  first.push({ id: 'b', amount: 2 });
  assert.deepEqual(second, [{ id: 'a', amount: 1 }]);
  assert.deepEqual(parseRecords('a,1'), [{ id: 'a', amount: 1 }]);
});
test('P1 parser recovers after duplicate failure', async () => {
  const { parseRecords } = await import('./records.mjs');
  assert.throws(() => parseRecords('a,1\na,2'));
  assert.deepEqual(parseRecords('a,1'), [{ id: 'a', amount: 1 }]);
});
import { mkdirSync, mkdtempSync, openSync, closeSync, readFileSync, rmSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
const appRoot = dirname(fileURLToPath(import.meta.url));
export function runCli(args, options = {}) {
  const tempRoot = join(appRoot, '.tmp');
  mkdirSync(tempRoot, { recursive: true });
  const folder = mkdtempSync(join(tempRoot, 'child-'));
  const stdoutPath = join(folder, 'stdout'), stderrPath = join(folder, 'stderr');
  let stdoutFd, stderrFd;
  try {
    stdoutFd = openSync(stdoutPath, 'w');
    stderrFd = openSync(stderrPath, 'w');
    const result = spawnSync(process.execPath, ['cli.mjs', ...args], {
      cwd: appRoot, env: { ...process.env, ...options.env },
      stdio: ['ignore', stdoutFd, stderrFd], timeout: 5000,
    });
    if (result.error) throw result.error;
    return { status: result.status, signal: result.signal,
      stdout: readFileSync(stdoutPath, 'utf8'), stderr: readFileSync(stderrPath, 'utf8') };
  } finally {
    if (stdoutFd !== undefined) closeSync(stdoutFd);
    if (stderrFd !== undefined) closeSync(stderrFd);
    rmSync(folder, { recursive: true, force: true });
  }
}
{
